Safari/537.36","ip":"178.89.40.17","created_at":"2026-10-02T15:10:00Z","last_used_at":"2026-10-22T19:41:00Z","mfa_passed":true,"current":false}]},"GET /counters":{"status":200,"body":{"notifications":3,"chats":3}},"GET /chats":{"status":200,"body":[{"id":7,"kind":"direct","title":"Дана Темирова","group_id":null,"unread":1,"last_message":{"text":"Рада слышать! Амина молодец, на прошлой неделе лучше всех отвечала у доски.","at":"2026-10-24T04:29:41.045749+00:00","sender":"Дана Темирова"},"other_user":{"id":8,"full_name":"Дана Темирова","kind":"staff","position":"Учитель"},"members":2,"about_student_id":null},{"id":8,"kind":"direct","title":"Динара Сапарова","group_id":null,"unread":2,"last_message":{"text":"При оплате сразу за двоих детей — скидка 5% на второго ребёнка.","at":"2026-10-21T08:29:41.359532+00:00","sender":"Динара Сапарова"},"other_user":{"id":4,"full_name":"Динара Сапарова","kind":"staff","position":"Офис-менеджер"},"members":2,"about_student_id":null}]},"GET /chats/contacts":{"status":200,"body":[{"id":2,"full_name":"Асем Кенжебаева","kind":"staff","position":"Админ филиала","subtitle":"Админ филиала"},{"id":1,"full_name":"Владелец One English","kind":"staff","position":"Владелец","subtitle":"Владелец"},{"id":8,"full_name":"Дана Темирова","kind":"staff","position":"Учитель","subtitle":"Учитель"},{"id":4,"full_name":"Динара Сапарова","kind":"staff","position":"Офис-менеджер","subtitle":"Офис-менеджер"}]},"GET /notifications":{"status":200,"body":{"unread":3,"items":[{"id":24,"at":"2026-10-25T08:00:12.846945Z","kind":"arrived","title":"Амина пришла на урок","body":"FF2-1 · 17:00, кабинет Каб. 2","link":"/portal/children/6","read":false},{"id":23,"at":"2026-10-25T08:00:12.791047Z","kind":"arrived","title":"Тимур пришёл на урок","body":"FF2-1 · 17:00, кабинет Каб. 2","link":"/portal/children/5","read":false},{"id":25,"at":"2026-10-24T12:30:12.910524Z","kind":"homework","title":"Новое задание для FF2-1","body":"Workbook стр. 24–25 и новые слова · до понедельника","link":"/portal/homework","read":false},{"id":26,"at":"2026-10-24T06:30:12.967869Z","kind":"coins","title":"Амина получила 50 коинов","body":"Победа в квизе","link":"/portal/coins","read":true},{"id":27,"at":"2026-10-22T08:30:13.024695Z","kind":"late","title":"Тимур опоздал на урок","body":"Опоздание 15 минут · FF2-1","link":"/portal/children/5","read":true},{"id":28,"at":"2026-10-21T08:30:13.082790Z","kind":"complaint","title":"Ответ на обращение «Холодно в кабинете»","body":"Школа ответила на ваше обращение","link":"/complaints","read":true},{"id":29,"at":"2026-10-13T08:30:13.148429Z","kind":"payment","title":"Оплата получена","body":"30 000 ₸ · 12 уроков · Тимур","link":"/portal/payments","read":true}]}},"GET /consents/my":{"status":200,"body":[]},"GET /complaints/my":{"status":200,"body":[{"id":1,"subject":"Холодно в кабинете","body":"Дети жалуются, что в кабинете 2 холодно по вечерам. Можно что-то сделать с отоплением?","status":"answered","created_at":"2026-10-19T08:29:41.810687Z","acknowledged_at":"2026-10-19T08:29:41.810687Z","due_at":"2026-10-28T08:29:41.738499Z","answer":"Спасибо, что написали! Мы установили в кабинете 2 дополнительный обогреватель и проверили батареи. Если станет холодно снова — напишите нам.","answered_at":"2026-10-21T08:29:41.810687Z","branch_id":1,"file_url":null}]},"GET /documents/rules":{"status":200,"body":{"id":1,"kind":"rules","version":"1.0","title":"Правила платформы One English","body":"Правила платформы One English.docx\nПравила платформы One English\nOct 21, 2026 · @One English\nОбщие положения\nПравила действуют в обоих филиалах — «Север» и «Янги шахар» — и на платформе One English. Каждая группа видит на платформе свой раздел и подтверждает его при регистрации.\nПринимая правила, пользователь соглашается с ними; без подтверждения доступ к платформе не открывается.\nВ классах ведётся видео- и аудиозапись. Каждый пользователь до первого урока подтверждает, что уведомлён, и даёт согласие — порядок в разделе «Видео- и аудиозапись: уведомление и согласие».\nШкола может обновлять правила; об изменениях пользователей уведомляют на платформе не позднее чем за 7 дней.\nЖалобы подаются на платформе напрямую администрации — порядок в разделе «Порядок жалоб».\nЛичные данные (телефоны, оплаты, оценки) используются только для учёбы и связи и не передаются третьим лицам.\nВидео- и аудиозапись: уведомление и согласие\nБез подписанного согласия студент не допускается к урокам, а преподаватель и сотрудник — к работе в классах.\nЧто и зачем записывается\nГде: во всех классах обоих филиалов, видео и звук, всё время работы школы.\nЗачем: контроль качества уроков, безопасность студентов и сотрудников, разбор спорных ситуаций.\nКто видит: операционный директор, методист, администратор филиала. Родители и третьи лица записи не получают.\nСрок хранения: 30 дней, затем запись удаляется автоматически. Фрагмент по жалобе или инциденту хранится до решения вопроса.\nЗаписи не публикуются и не используются в рекламе без отдельного письменного согласия.\nКак предупреждаем\nНа двери каждого класса — табличка «Ведётся видео- и аудиозапись».\nПункт о записи — в договоре со студентом и в трудовом договоре.\nНа платформе при регистрации — экран с текстом уведомления, его нельзя пропустить.\nАдминистратор устно напоминает о записи на первом пробном уроке.\nКто даёт согласие\nПлатформа хранит дату, время и версию подписанного текста согласия.\nДействующим студентам и сотрудникам согласие нужно собрать до запуска платформы; кто не подписал — платформа показывает это администратору.\nСогласие можно отозвать письменным заявлением. Поскольку запись ведётся во всех классах, после отзыва школа предлагает другой формат (например, индивидуальные онлайн-занятия) или прекращает договор.\nТекст согласия (для платформы и договора)\nЯ, ________, уведомлён(а), что в классах школы One English ведётся видео- и аудиозапись. Даю согласие на запись с моим участием (участием моего ребёнка ________) для контроля качества обучения и безопасности. Записи хранятся 30 дней, доступны только администрации школы и не передаются третьим лицам. Я могу отозвать согласие письменным заявлением. Дата ________ Подпись ________\nТекст согласия и срок хранения стоит проверить у юриста на соответствие закону о персональных данных.\nПорядок жалоб\nСтуденты, родители и сотрудники пишут жалобу на платформе напрямую администрации школы — без посредников.\nЖалоба подаётся в разделе «Жалобы и предложения» в личном кабинете. Можно приложить фото или документ.\nЖалобу видят только администрация и операционный директор; преподаватель или сотрудник, на которого жалуются, её не видит.\nАдминистрация подтверждает получение в течение 24 часов и даёт ответ в течение 3 рабочих дней.\nЕсли нужна проверка (например, по видеозаписи урока), срок продлевается до 7 рабочих дней, о чём автор жалобы получает уведомление.\nОтвет и принятое решение приходят автору в кабинет; если решение не устраивает, его можно обжаловать операционному директору.\nЖалоба не влияет на отношение к студенту или сотруднику; преследование за жалобу запрещено.\nЗаведомо ложные и оскорбительные жалобы рассматриваются как нарушение правил.\nПравила для студентов\nСтудент приходит вовремя, готовится к уроку и уважает группу; за оплату и пропуски отвечает он сам или его родитель.\nПосещение\nПриходить за 5 минут до начала урока. Опоздание больше 15 минут отмечается как пропуск.\nО пропуске предупреждать на платформе или администратору не позднее чем за 3 часа до урока.\nПропущенный урок без предупреждения не переносится и считается проведённым.\nОтработка пропуска по уважительной причине (болезнь со справкой) — по согласованию с администратором.\nУчёба\nВыполнять домашние задания на платформе до следующего урока.\nПриносить учебник и тетрадь; учебник покупается в школе.\nНа уроке говорить по-английски, насколько позволяет уровень.\nПроходить промежуточные и итоговые тесты; по их результатам решается переход на следующий уровень.\nГруппы, уровни и филиалы\nНовый студент после первых 3 занятий в группе вправе один раз бесплатно сменить преподавателя или группу. Заявка подаётся на платформе; администратор предлагает варианты в течение 3 рабочих дней.\nСтудент может экстренно сдать итоговый тест (final) досрочно. При успешной сдаче он переводится на уровень выше в ближайшую группу этого уровня.\nЕсли итоговый тест не сдан, студент повторяет уровень. Повторный final — по окончании повторного курса.\nПеревод в другой филиал — по заявлению на платформе, при наличии места в группе нужного уровня. Оплата и остаток уроков переносятся без изменений.\nПоведение\nТелефон на уроке — только по заданию преподавателя.\nУважать преподавателя и одногруппников: без оскорблений, насмешек и помех уроку.\nБережно относиться к имуществу школы; за порчу платит студент или родитель.\nНе есть в классе; вода разрешена.\nОплата и заморозка\nОплата за месяц вносится до первого урока месяца.\nПри неоплате более 5 дней доступ к урокам и платформе приостанавливается.\nЗаморозка обучения — по заявлению, не дольше 1 месяца за курс, при условии предоплаты за месяц. Предоплата засчитывается в оплату первого месяца после выхода из заморозки.\nВозврат денег не предусмотрен, в том числе за пропущенные уроки и при досрочном прекращении обучения.\nПлатформа\nОдин аккаунт — один студент; не передавать логин и пароль другим.\nНе публиковать материалы и записи уроков за пределами платформы.\nПравила для детей\nКороткая версия для студентов до 12 лет: её показывают на первом уроке и вешают в каждом классе. Полные правила за ребёнка принимает родитель.\nЯ прихожу на урок вовремя.\nЯ приношу учебник, тетрадь и ручку.\nЯ стараюсь говорить на уроке по-английски.\nЯ поднимаю руку, когда хочу сказать.\nЯ слушаю учителя и не мешаю другим.\nМой телефон спит в рюкзаке, пока учитель не разрешит.\nЯ не обижаю других ребят — ни словами, ни руками.\nЯ берегу вещи в классе.\nЯ делаю домашнее задание.\nПосле урока меня сразу забирает мама, папа или взрослый, о котором знает школа.\nВ классе работает камера — она помогает, чтобы на уроке всем было хорошо и безопасно.\nЗа соблюдение правил преподаватель отмечает ребёнка звёздочкой на платформе; звёздочки видят родители.\nПравила для родителей\nРодитель отвечает за оплату, посещение и связь со школой, если студенту меньше 18 лет.\nОплата и документы\nВносить оплату до первого урока месяца; чек и история платежей доступны в личном кабинете.\nЗаключить договор при записи и держать контактные данные на платформе актуальными.\nПосещение и безопасность\nПриводить ребёнка ко времени начала урока и забирать сразу после окончания. Школа отвечает за ребёнка только во время урока; до начала и после окончания урока ответственность несёт родитель.\nЕсли ребёнка забирает другой человек — заранее сообщить администратору его имя.\nНе приводить ребёнка с признаками болезни.\nВо время урока не заходить в класс; наблюдать за уроком — только на открытых уроках.\nСвязь со школой\nСледить за оценками, посещаемостью и домашними заданиями в кабинете родителя.\nВопросы по учёбе задавать преподавателю через платформу, по оплате и расписанию — администратору.\nСообщения преподавателю — с 9:00 до 20:00; ответ в течение 24 часов.\nПриходить на родительские встречи по итогам уровня (раз в 3 месяца).\nОбщение\nОбщаться с преподавателями и сотрудниками уважительно; конфликты решать с администратором, а не при детях.\nНе просить у преподавателя личный номер и не договариваться о частных уроках в обход школы.\nПравила для преподавателей\nПреподаватель ведёт урок по программе, вовремя отмечает всё на платформе и отвечает за качество, которое проверяется по видеозаписям уроков.\nПунктуальность\nБыть в филиале за 15 минут до первого урока; урок начинается и заканчивается строго по расписанию.\nОпоздание фиксируется по камере; три опоздания за месяц — разговор с методистом, далее штраф по положению о зарплате.\nО болезни или замене сообщать администратору не позднее чем за 24 часа (в экстренном случае — сразу, звонком).\nУрок\nГотовить план урока по программе уровня; урок без плана не проводится.\nНе менее 70% урока студенты говорят и работают, а не слушают преподавателя.\nВести урок на английском; русский или казахский — только для объяснения сложного.\nТелефон преподавателя на уроке не используется в личных целях.\nПлатформа — в день урока\nОтмечать посещаемость в течение 10 минут после начала урока.\nВыставлять оценки и задавать домашнее задание до 22:00 того же дня.\nПроверять домашние задания в течение 48 часов.\nРаз в месяц писать короткий отзыв о каждом студенте для родителей.\nВнешний вид и поведение\nДеловой или аккуратный повседневный стиль; бейдж школы обязателен.\nУважительное отношение к студентам: без крика, оскорблений, физического контакта и любимчиков.\nОбщение со студентами и родителями — только через платформу или рабочий номер; без личных переписок с несовершеннолетними.\nЧастные уроки студентам школы в обход школы запрещены.\nОценка работы\nМетодист смотрит минимум 2 записи уроков каждого преподавателя в месяц по критериям: пунктуальность, качество урока, вовлечённость студентов, знание предмета, поведение.\nРезультаты обсуждаются с преподавателем раз в месяц и влияют на премию.\nПравила для сотрудников\nСотрудник ведёт всю работу с клиентами через платформу, отвечает быстро и сдаёт ежедневный отчёт; согласие на видео- и аудиозапись подписывается при приёме на работу.\nДля всех сотрудников\nРабочий день — по графику филиала; приход и уход отмечаются на платформе.\nКаждый клиент, звонок, оплата и заморозка вносятся в платформу в тот же день — нет записи, значит, не было.\nЕжедневный отчёт по своему участку — до 20:00.\nНе передавать доступ к платформе другим; данные клиентов не копировать в личные телефоны и мессенджеры.\nОбщение с клиентами — вежливое, на «вы», на русском, казахском или английском по выбору клиента.\nАдминистраторы филиалов\nВстречать студентов и родителей, следить за порядком в классах и расписанием.\nПринимать оплату только с чеком через платформу; наличные — в кассу в тот же день.\nОформлять договор и согласие на видео- и аудиозапись до первого урока каждого нового студента.\nНаходить замену заболевшему преподавателю и сообщать группе не позднее чем за 2 часа.\nОтдел продаж\nПерезванивать на пропущенный звонок в течение 15 минут в рабочее время.\nНовую заявку обрабатывать в течение 1 часа и записывать на пробный урок.\nПосле пробного урока связываться с клиентом в тот же день.\nКаждый звонок отмечать в платформе с результатом (записан, думает, отказ и причина).\nНе обещать скидок и условий, не утверждённых руководством.\nSMM\nПубликовать контент по согласованному контент-плану в Instagram и TikTok @1eng.kz.\nОтвечать на комментарии и сообщения в течение 2 часов в рабочее время; заявки передавать в отдел продаж.\nСнимать студентов и преподавателей только с их отдельного согласия (для детей — согласия родителя); записи камер из классов в соцсети не выкладываются.\nЕженедельно заполнять «SMM-отчётность One English».\nЧто настроить под школу\nЦифры в правилах — типовые для языковых школ; перед запуском их нужно подтвердить.\n☐ Сроки: предупреждение о пропуске (3 ч), отметка опоздания (15 мин), неоплата до блокировки (5 дней)\n☐ Заморозка: максимальный срок и сколько раз за курс\n☐ Привести договор в соответствие: возврат не предусмотрен, заморозка — с предоплатой за месяц\n☐ Срок хранения видео- и аудиозаписей (30 дней) и кто имеет к ним доступ\n☐ Что делать, если студент или сотрудник отказывается от записи\n☐ Штрафы и премии преподавателей — ссылка на положение о зарплате\n☐ Проверка юристом: договор, согласие на запись, обработка персональных данных\nГруппа | Кто подписывает | Как | Когда\nСтудент 18+ | Сам студент | Галочка на платформе + подпись в договоре | До первого урока, включая пробный\nСтудент до 18 лет | Родитель или законный представитель | Галочка в кабинете родителя + подпись в договоре | До первого урока, включая пробный\nПреподаватель | Сам преподаватель | Отдельное согласие к трудовому договору | В день приёма на работу\nСотрудник | Сам сотрудник | Отдельное согласие к трудовому договору | В день приёма на работу","effective_from":"2026-09-25T08:27:09.192648Z","upcoming":null}},"GET /documents/recording":{"status":200,"body":{"id":2,"kind":"recording","version":"1.0","title":"Согласие на видео- и аудиозапись","body":"Я уведомлён(а), что в классах школы One English ведётся видео- и аудиозапись. Даю согласие на запись с моим участием (участием моего ребёнка) для контроля качества обучения и безопасности. Записи хранятся 30 дней, доступны только администрации школы и не передаются третьим лицам. Согласие можно отозвать.","effective_from":"2026-09-25T08:27:09.192724Z","upcoming":null}},"GET /portal/students/6/schedule#1":{"status":200,"body":[{"id":1,"starts_at":"2026-10-12T10:00:00Z","ends_at":"2026-10-12T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","status":"done","cancel_reason":null,"topic":null},{"id":2,"starts_at":"2026-10-14T10:00:00Z","ends_at":"2026-10-14T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","status":"done","cancel_reason":null,"topic":null},{"id":3,"starts_at":"2026-10-16T10:00:00Z","ends_at":"2026-10-16T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","status":"done","cancel_reason":null,"topic":null},{"id":4,"starts_at":"2026-10-19T10:00:00Z","ends_at":"2026-10-19T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","status":"done","cancel_reason":null,"topic":null},{"id":5,"starts_at":"2026-10-21T10:00:00Z","ends_at":"2026-10-21T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","status":"done","cancel_reason":null,"topic":null},{"id":6,"starts_at":"2026-10-23T10:00:00Z","ends_at":"2026-10-23T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","status":"done","cancel_reason":null,"topic":null},{"id":7,"starts_at":"2026-10-26T10:00:00Z","ends_at":"2026-10-26T11:30:00Z","group":"FF2-1","room":"Каб. 1","teacher":"Дана Темирова","sta